<script setup lang="ts">import {ref,onMounted,watch,computed} from 'vue';import {useResearch} from '../stores/research';import {useSamples} from '../stores/samples';import {useAuth} from '../stores/auth';import {createStudy} from '../api/studies';import {useTask} from '../hooks/useTask';import {number} from '../utils/format';import PageHeading from '../components/common/PageHeading.vue';import ErrorNotice from '../components/common/ErrorNotice.vue';import StudySelect from '../components/StudySelect.vue';import CellMatrix from '../components/CellMatrix.vue';const lab=useResearch(),samples=useSamples(),auth=useAuth(),selected=ref(0),cell=ref(0),offset=ref(0),show=ref(false),data=ref({code:'',name:'',source_file:'bh-new-trials.csv',a_levels:'1180,1220,1260',b_levels:'薄釉,厚釉',csv_text:'specimen_code,temperature,glaze,strength_mpa\n'}),{busy,error,perform}=useTask();const study=computed(()=>lab.studies.find(s=>s.id===selected.value));async function load(){if(selected.value)await samples.load(selected.value,cell.value,offset.value);}onMounted(()=>perform(async()=>{await lab.load();selected.value=lab.studies[0]?.id||0;await load();}));watch(selected,()=>{cell.value=0;offset.value=0;perform(load);});watch(cell,()=>{offset.value=0;perform(load);});function submit(){perform(async()=>{const result=await createStudy({...data.value,a_levels:data.value.a_levels.split(',').map(x=>x.trim()),b_levels:data.value.b_levels.split(',').map(x=>x.trim()),note:'团队导入的随机独立试片试验'});await lab.load();selected.value=result.id;show.value=false;});}</script><template><PageHeading index="02" title="每个处理格，都有独立试片" text="检查完整交叉、每格重复数与全试验唯一试片编号；当前不接受重复测量。"><button v-if="auth.canEdit" class="outline" @click="show=!show">{{show?'收起导入':'导入独立试验 +'}}</button></PageHeading><ErrorNotice :message="error" @retry="perform(load)"/><form v-if="show" class="research-form import-form" @submit.prevent="submit"><h2>导入完整平衡试验</h2><div class="form-grid"><label>试验编号<input v-model="data.code" required minlength="2"></label><label>试验名称<input v-model="data.name" required minlength="2"></label><label>温度水平 / 英文逗号<input v-model="data.a_levels" required></label><label>釉层水平 / 英文逗号<input v-model="data.b_levels" required></label></div><label>CSV内容<textarea v-model="data.csv_text" rows="6" required></textarea></label><p class="input-note">每格至少3个独立观测且样本数相同，试片编号全试验唯一，最多3000行；强度为有限正数。</p><button class="primary" :disabled="busy">校验并保存试验 →</button></form><div class="data-toolbar"><StudySelect v-model="selected" :studies="lab.studies"/><label>处理格<select v-model="cell"><option :value="0">全部处理格</option><option v-for="c in samples.cells" :key="c.id" :value="c.id">{{c.temperature}}°C / {{c.glaze}} / {{c.n}}片</option></select></label></div><p class="source-note">{{study?.source_file}} <span>{{study?.note}}</span></p><CellMatrix :cells="samples.cells" :a="study?.a_levels||[]" :b="study?.b_levels||[]"/><div class="table-wrap readings-table"><table><thead><tr><th>独立试片</th><th>温度 °C</th><th>釉层</th><th>抗折强度 MPa</th></tr></thead><tbody><tr v-for="r in samples.rows" :key="r.id"><td><b>{{r.specimen_code}}</b></td><td>{{r.temperature}}</td><td>{{r.glaze}}</td><td>{{number(r.strength_mpa,5)}}</td></tr></tbody></table></div><div class="pagination"><span>共{{samples.total}}片 / {{offset+1}}—{{Math.min(offset+20,samples.total)}}</span><div><button :disabled="offset===0" @click="offset-=20;perform(load)">← 前20片</button><button :disabled="offset+20>=samples.total" @click="offset+=20;perform(load)">后20片 →</button></div></div></template>
